    public void cloneTextNodeReturnsCloneWhenNodeIsText() {
        // Arrange
        String text = "Hello World";
        TextNode textNode = new TextNode(text);

        // Act
        TextNode result = textNode.clone();

        // Assert
        assertNotNull(result.text());
        assertEquals(text, result.text());
    }

